refentry.refsect1:
  &reftitle.examples;

   Exemple avec Yaf_Dispatcher::autoRender


<?php
class IndexController extends Yaf_Controller_Abstract {
     /* la méthode init sera appelée dès qu'un contrôleur sera initialisé */
     public function init() {
         if ($this->getRequest()->isXmlHttpRequest()) {
             //n'appelle pas render pour une requête ajax
             //une chaîne json sera affichée
             Yaf_Dispatcher::getInstance()->autoRender(FALSE);
         }
     }
}
?>
